class Solution:
    def solve(self, head):
        if not head:
            return head

        even_head = even = ListNode(0)
        odd_head = odd = ListNode(0)

        while head:
            if head.val % 2 == 0:
                even.next = head
                even = even.next
            else:
                odd.next = head
                odd = odd.next
            head = head.next

        even.next = odd_head.next
        odd.next = None

        return even_head.next
